// SafeWeb shared protocol — the single source of truth for the contract
// between the on-device extension/agent and the accountability server.
//
// Everything that both sides must agree on (API paths, event shapes,
// severities, config schema) lives here so there is exactly one definition.

export const PROTOCOL_VERSION = 1;

// ---------------------------------------------------------------------------
// API surface
// ---------------------------------------------------------------------------
// Paths are versioned so old clients keep working after server upgrades.
export const API = {
  base: `/api/v${PROTOCOL_VERSION}`,
  // Device (on-device client) endpoints — authenticated with a device token.
  events: `/api/v${PROTOCOL_VERSION}/events`, // POST  batch of events
  config: `/api/v${PROTOCOL_VERSION}/config`, // GET   latest filter config
  heartbeat: `/api/v${PROTOCOL_VERSION}/heartbeat`, // POST device liveness ping
  // Enrollment — pairs a device with an accountability partner.
  enrollClaim: `/api/v${PROTOCOL_VERSION}/enroll/claim`, // POST device claims a code
  enrollCreate: `/api/v${PROTOCOL_VERSION}/enroll/code`, // POST partner mints a code
  // Partner (accountability partner / parent) endpoints — session authed.
  partnerLogin: `/api/v${PROTOCOL_VERSION}/partner/login`,
  partnerLogout: `/api/v${PROTOCOL_VERSION}/partner/logout`,
  partnerMe: `/api/v${PROTOCOL_VERSION}/partner/me`,
  reports: `/api/v${PROTOCOL_VERSION}/partner/reports`, // GET activity + summaries
  devices: `/api/v${PROTOCOL_VERSION}/partner/devices`, // GET managed devices
  settings: `/api/v${PROTOCOL_VERSION}/partner/settings`, // GET/PUT trigger + block config
  stream: `/api/v${PROTOCOL_VERSION}/partner/stream`, // GET SSE live alerts
};

// ---------------------------------------------------------------------------
// Event model
// ---------------------------------------------------------------------------
// Every observation the on-device client makes is an Event. Keeping the set
// small and explicit makes the accountability report legible to a human.
export const EVENT_TYPES = Object.freeze({
  BLOCKED_SITE: 'blocked_site', // navigation to a blocklisted domain was stopped
  TRIGGER_WORD: 'trigger_word', // a trigger word appeared (url, query, or page text)
  BYPASS_ATTEMPT: 'bypass_attempt', // user tried to disable/circumvent protection
  PROTECTION_OFF: 'protection_off', // protection was turned off / extension removed
  PROTECTION_ON: 'protection_on', // protection (re)activated
  HEARTBEAT_MISSED: 'heartbeat_missed', // server-side: device went silent
  ALLOWED_VISIT: 'allowed_visit', // optional low-signal browsing record (opt-in)
});

// Severity drives alerting. High-severity events notify the partner immediately;
// lower severities roll up into the periodic report.
export const SEVERITY = Object.freeze({
  INFO: 'info',
  LOW: 'low',
  MEDIUM: 'medium',
  HIGH: 'high',
});

export const SEVERITY_RANK = Object.freeze({ info: 0, low: 1, medium: 2, high: 3 });

// Default severity for each event type. A trigger word's own category severity
// (see data/triggers.json) can raise this at classification time.
export const DEFAULT_SEVERITY = Object.freeze({
  [EVENT_TYPES.BLOCKED_SITE]: SEVERITY.HIGH,
  [EVENT_TYPES.TRIGGER_WORD]: SEVERITY.MEDIUM,
  [EVENT_TYPES.BYPASS_ATTEMPT]: SEVERITY.HIGH,
  [EVENT_TYPES.PROTECTION_OFF]: SEVERITY.HIGH,
  [EVENT_TYPES.PROTECTION_ON]: SEVERITY.INFO,
  [EVENT_TYPES.HEARTBEAT_MISSED]: SEVERITY.MEDIUM,
  [EVENT_TYPES.ALLOWED_VISIT]: SEVERITY.INFO,
});

// Which severities trigger an immediate push to the accountability partner.
export const IMMEDIATE_ALERT_MIN_SEVERITY = SEVERITY.HIGH;

/**
 * Validate and normalize an inbound event from a device. Returns
 * `{ ok: true, event }` or `{ ok: false, error }`. Never throws — the server
 * uses this to reject malformed input without crashing.
 *
 * @param {any} raw
 * @param {{ now?: number }} [opts]
 */
export function normalizeEvent(raw, opts = {}) {
  const now = opts.now ?? nowMs();
  if (raw == null || typeof raw !== 'object') {
    return { ok: false, error: 'event must be an object' };
  }
  const type = raw.type;
  if (!Object.values(EVENT_TYPES).includes(type)) {
    return { ok: false, error: `unknown event type: ${String(type)}` };
  }
  // Client timestamps are advisory (device clocks drift / can be tampered).
  // We keep the client value but stamp an authoritative server receipt time.
  let clientTs = Number(raw.ts);
  if (!Number.isFinite(clientTs)) clientTs = now;

  const severity = Object.values(SEVERITY).includes(raw.severity)
    ? raw.severity
    : DEFAULT_SEVERITY[type];

  const event = {
    type,
    severity,
    ts: clientTs, // device-reported time (advisory)
    receivedTs: now, // server-authoritative time
    url: sanitizeString(raw.url, 2048),
    domain: sanitizeString(raw.domain, 253),
    // `context` is a short redacted snippet (never the full page) — see
    // matcher.redactSnippet. We hard-cap length defensively here too.
    context: sanitizeString(raw.context, 280),
    category: sanitizeString(raw.category, 64),
    matchedTerms: Array.isArray(raw.matchedTerms)
      ? raw.matchedTerms.slice(0, 20).map((t) => sanitizeString(t, 64)).filter(Boolean)
      : [],
    detail: sanitizeString(raw.detail, 280),
  };
  return { ok: true, event };
}

/**
 * @param {unknown} v
 * @param {number} max
 * @returns {string|undefined}
 */
function sanitizeString(v, max) {
  if (v == null) return undefined;
  let s = String(v);
  // Strip control chars that could corrupt logs / dashboards.
  s = s.replace(/[\u0000-\u001f\u007f]/g, ' ').trim();
  if (s.length === 0) return undefined;
  return s.length > max ? s.slice(0, max) : s;
}

// ---------------------------------------------------------------------------
// Config schema (server -> device)
// ---------------------------------------------------------------------------
// The device pulls this and enforces it locally. `revision` lets the device
// skip re-applying identical config.
/**
 * @typedef {Object} FilterConfig
 * @property {number} protocolVersion
 * @property {number} revision              monotonically increasing
 * @property {string[]} blockedCategories   categories from the blocklist to enforce
 * @property {string[]} customBlockedDomains extra domains to block
 * @property {string[]} allowedDomains      allowlist overrides (e.g. medical/edu)
 * @property {string[]} triggerCategories   trigger categories to scan for
 * @property {string[]} customTriggerWords  partner-added words
 * @property {boolean} scanPageText         scan visible page text, not just URLs
 * @property {boolean} recordAllowedVisits  low-signal browsing history (opt-in)
 * @property {number} heartbeatSeconds      how often the device pings
 */

/** @returns {FilterConfig} */
export function defaultConfig() {
  return {
    protocolVersion: PROTOCOL_VERSION,
    revision: 1,
    blockedCategories: ['adult', 'nudity', 'dating-explicit'],
    customBlockedDomains: [],
    allowedDomains: [],
    triggerCategories: ['explicit', 'solicitation'],
    customTriggerWords: [],
    scanPageText: true,
    recordAllowedVisits: false,
    heartbeatSeconds: 300,
  };
}

// Milliseconds "now". Isolated so tests can stub it and so the workflow
// sandbox's Date restrictions never leak into shared logic paths under test.
export function nowMs() {
  return Date.now();
}
